import { FactorKey as FactorKeys } from "@/contracts";
import { shortFromTitle } from "./authored/short-names";

type Ep = typeof endpoints;
type In<T> = T extends z.ZodType ? z.output<T> : undefined;
export interface Ctx<K extends EndpointName> {
  params: Record<string, string>;
  query: Ep[K] extends { query: infer Q } ? In<Q> : Record<string, never>;
  body: Ep[K] extends { body: infer B } ? In<B> : undefined;
  user: User;
}
type Out<K extends EndpointName> = z.input<Ep[K]["response"]>;
type Handlers = { [K in EndpointName]: (ctx: Ctx<K>) => Out<K> | Promise<Out<K>> };

// ---------- helpers ----------
const findCase = (d: Dataset, id: string) => must(d.cases.find((c) => c.id === id), `Case ${id}`);
const findReq = (d: Dataset, id: string) => must(d.requirements.find((r) => r.id === id), `Requirement ${id}`);
const head = (d: Dataset) => d.users.find((u) => u.role === "head")!;
const userName = (d: Dataset, id: string) => d.users.find((u) => u.id === id)?.name ?? id;
 */

const Id = z.string().min(1);
const IsoDate = z.string(); // ISO 8601
const Factors = z.record(FactorKey, z.number().min(0).max(1));

// ---------- People and workspaces ----------
export const User = z.object({
  id: Id,
  name: z.string(),
  initials: z.string(),
  role: Role,
  title: z.string(),
  series: z.array(Series),
  region: Region,
  attributeScope: z.string().optional(),
  color: z.string(),
  synthetic: z.boolean(),
});
export type User = z.infer<typeof User>;

export const SourceFilter = z.object({
  excludeSocial: z.boolean(),
  ownersOnly: z.boolean(),
  minTrust: z.enum(["A", "B", "C", "D", "E"]),
});
export type SourceFilter = z.infer<typeof SourceFilter>;

export const Watchlist = z.object({
  competitors: z.array(z.string()),
  topics: z.array(z.string()),
  domains: z.array(z.string()),
  languages: z.array(z.string()),
});
export type Watchlist = z.infer<typeof Watchlist>;

export const Workspace = z.object({
  id: Id,
  userId: Id,
  series: Series,
  region: Region,
  projectType: ProjectType,
  weightProfileId: Id,
  sourceFilter: SourceFilter,
  watchlist: Watchlist,
});
export type Workspace = z.infer<typeof Workspace>;

export const WeightProfile = z.object({
  id: Id,
  name: z.string(),
  description: z.string(),
  ownerId: Id.nullable(), // null = default profile owned by the head of product line
  isDefault: z.boolean(),
  weights: Factors,
  /** Requirement rank = case score x multiplier for its cost size. */
  costMultiplier: z.record(CostSize, z.number()),
});
export type WeightProfile = z.infer<typeof WeightProfile>;

export const BrandPillar = z.object({ name: z.string(), description: z.string() });
export const BrandProfile = z.object({
  version: z.number().int(),
  updatedAt: IsoDate,
  updatedBy: Id,
  pillars: z.array(BrandPillar),
  doNot: z.array(z.string()),
  notesMd: z.string(),
});
export type BrandProfile = z.infer<typeof BrandProfile>;

// ---------- Signals (FINDING) ----------
export const SignalMetric = z.object({ name: z.string(), value: z.number(), unit: z.string(), cycle: z.string().optional() });

export const Signal = z.object({
  id: Id,
    public status: number,
    message: string,
  ) {
    super(message);
  }
}

export function must<T>(value: T | undefined | null, what: string): T {
  if (value === undefined || value === null) throw new ApiError(404, `${what} not found`);
  return value;
}
