    ownerId: null,
    isDefault: p.is_default,
    weights: weightsFromBackend(p.case_weights),
    costMultiplier: { S: p.cost_multipliers.S ?? 1, M: p.cost_multipliers.M ?? 0.85, L: p.cost_multipliers.L ?? 0.7 },
  };
}

