export const backendHandlers: Partial<Handlers> = {
  // Identity
  me: async ({ user }) => {
    const { config, profileId } = await activeConfig(user);
    const profiles = await profilesOf(user, config.id);
    const profile = profiles.find((p) => p.id === profileId) ?? profiles[0];
