9	
10	export type QueryValue = string | number | boolean | undefined | null | (string | number)[];
11	
12	export function qs(query: Record<string, QueryValue> = {}): string {
13	  const p = new URLSearchParams();
14	  for (const [k, v] of Object.entries(query)) {
15	    if (v === undefined || v === null || v === "") continue;
16	    // FastAPI list parameters repeat the key: state=open&state=confirmed
17	    if (Array.isArray(v)) v.forEach((x) => p.append(k, String(x)));
18	    else p.append(k, String(v));
